transient Node<K,V>[] table;
transient int size;
int threshold;              // 容量 * loadFactor
final float loadFactor;
transient int modCount;

static final int hash(Object key) {
  int h;
  return (key == null) ? 0 : (h = key.hashCode()) ^ (h >>> 16);
}

// 下标计算：n 是 2 的幂时，与运算等价于取模
int index = (n - 1) & hash;

static final int tableSizeFor(int cap) {
  int n = cap - 1;
  n |= n >>> 1; n |= n >>> 2; n |= n >>> 4; n |= n >>> 8; n |= n >>> 16;
  return (n < 0) ? 1 : (n >= MAXIMUM_CAPACITY) ? MAXIMUM_CAPACITY : n + 1;
}
// tableSizeFor(17) == 32, tableSizeFor(16) == 16, tableSizeFor(100) == 128

final V putVal(int hash, K key, V value, boolean onlyIfAbsent, boolean evict) {
  Node<K,V>[] tab; Node<K,V> p; int n, i;
  if ((tab = table) == null || (n = tab.length) == 0)
    n = (tab = resize()).length;                       // 懒初始化
  if ((p = tab[i = (n - 1) & hash]) == null)
    tab[i] = newNode(hash, key, value, null);          // 空桶直插
  else {
    Node<K,V> e; K k;
    if (p.hash == hash && ((k = p.key) == key || (key != null && key.equals(k))))
      e = p;                                           // 首节点就是目标
    else if (p instanceof TreeNode)
      e = ((TreeNode<K,V>)p).putTreeVal(this, tab, hash, key, value);   // 树插入
    else {
      for (int binCount = 0; ; ++binCount) {
        if ((e = p.next) == null) {
          p.next = newNode(hash, key, value, null);    // 尾插
          if (binCount >= TREEIFY_THRESHOLD - 1) treeifyBin(tab, hash);
          break;
        }
        if (e.hash == hash && ((k = e.key) == key || (key != null && key.equals(k)))) break;
        p = e;
      }
    }
    if (e != null) { V old = e.value; if (!onlyIfAbsent || old == null) e.value = value; return old; }
  }
  ++modCount;
  if (++size > threshold) resize();
  return null;
}

static final int TREEIFY_THRESHOLD = 8;      // 链表 -> 树的阈值
static final int UNTREEIFY_THRESHOLD = 6;    // 树 -> 链表的阈值
static final int MIN_TREEIFY_CAPACITY = 64;  // 小于此容量优先扩容

