class LruCache<K,V> extends java.util.LinkedHashMap<K,V> {
  private final int max;
  LruCache(int max){
    super(max, 0.75f, true);   // accessOrder = true
    this.max = max;
  }
  @Override protected boolean removeEldestEntry(java.util.Map.Entry<K,V> eldest){
    return size() > max;       // 超过容量就淘汰最久未使用的
  }
}

